package com.hospital.system.controller; import com.hospital.system.model.Doctor; import com.hospital.system.service.DoctorService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/doctors") public class DoctorController {private final DoctorService s; public DoctorController(DoctorService s){this.s=s;} @GetMapping public Object all(@RequestParam(defaultValue="") String q){return s.all(q);} @GetMapping("/{id}") public Doctor one(@PathVariable Long id){return s.one(id);} @PostMapping public ResponseEntity<Doctor> add(@RequestBody Doctor x){return ResponseEntity.status(201).body(s.add(x));} @PutMapping("/{id}") public Doctor update(@PathVariable Long id,@RequestBody Doctor x){return s.update(id,x);} @DeleteMapping("/{id}") public ResponseEntity<Void> del(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();} }
